// Source: net.minecraft.world.item.trading.TradeSets (WANDERING_TRADER_*)
//
// data/wandering_trader_trades.json is generated by scripts/build-villager-trades.mjs
// from trade_set/wandering_trader/{buying,uncommon,common}.json. WanderingTrader.updateTrades
// appends the three sets in that order: 2 buying, 2 uncommon and 5 common offers.

import type { ItemRegistry } from '../../item/Item.js';
import { MerchantOffer, type TradeSpec } from '../../item/trading/MerchantOffer.js';
import type { RandomSource } from '../../../core/Random.js';

export interface WanderingTradeSet {
  name: string;
  amount: number;
  allowDuplicates: boolean;
  trades: TradeSpec[];
}
export interface WanderingTradeData {
  sets: WanderingTradeSet[];
}

export class WanderingTraderTrades {
  /** Loaded by Game; WanderingTrader reads it when building its offers. */
  static current: WanderingTraderTrades | null = null;

  constructor(readonly data: WanderingTradeData) {}

  static async load(base = '/data'): Promise<WanderingTraderTrades> {
    try {
      const res = await fetch(`${base}/wandering_trader_trades.json`);
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const manager = new WanderingTraderTrades(await res.json() as WanderingTradeData);
      WanderingTraderTrades.current = manager;
      return manager;
    } catch (err) {
      console.warn('[trades] wandering_trader_trades.json unavailable:', err);
      const empty = new WanderingTraderTrades({ sets: [] });
      WanderingTraderTrades.current = empty;
      return empty;
    }
  }

  /** AbstractVillager.addOffersFromTradeSet for the three wandering trader sets. */
  createOffers(registry: ItemRegistry, random: RandomSource): MerchantOffer[] {
    const offers: MerchantOffer[] = [];
    for (const set of this.data.sets) {
      const pool = set.trades.slice();
      const count = Math.min(set.amount, pool.length);
      for (let i = 0; i < count; i++) {
        let spec: TradeSpec | undefined;
        if (set.allowDuplicates) {
          spec = pool[random.nextInt(pool.length)];
        } else {
          spec = pool.splice(random.nextInt(pool.length), 1)[0];
        }
        if (!spec) break;
        offers.push(new MerchantOffer(spec, registry, random, 1));
      }
    }
    return offers;
  }
}
